                        editionNo: { range: [1, 50], minlength: 1, maxlength: 30, required: !0 },
                        publicationNo: { range: [1, 10], minlength: 1, maxlength: 10, required: !0 },
                        publicationQuantity: { range: [1, 50], minlength: 1, maxlength: 50, required: !0 },
                        publicationPages: { range: [10, 5000], minlength: 2, maxlength: 5000, required: !0 },
                        registrationDateType: { required: !0 },
                        registrationDate11: { required: !0 },
                        registrationDate12: { required: !0 },
                        registrationDate13: { required: !0 },
                        registrationDate14: { required: !0 },
                        registrationDate15: { required: !0 },
                        registrationDate16: { required: !0 },
                        registrationDate21: { required: !0 },
